def is_valid_email(email):
    if '@' not in email or '.' not in email:
        return False
    parts = email.split('@')
    if len(parts) != 2:
        return False
    local, domain = parts
    if not local or not domain:
        return False
    if '..' in email:
        return False
    return True

def process_emails(emails, users):
    valid_emails = []
    for email in emails:
        if is_valid_email(email):
            valid_emails.append(email)
        else:
            print(f"Invalid email: {email}")

    shared_users = set()
    for email in valid_emails:
        if email in users:
            shared_users.add(users[email])
        else:
            print(f"Email not found in users: {email}")

    return shared_users
